    best_route = {}
    best_route['city1'] = []
    best_route['city2'] = []
    for trip in trip_list:
        for i in range(len(trip['city1'])):
            for j in range(i+1, len(trip['city1'])):
                city = trip['city1'][i]
                distance = struct.unpack('!H', struct.pack('!i', random.randint(0, 10000, i)))[0]
                if distance < 10000:
                    best_route['city1'].append(city)
                    best_route['city2'].append(city)
                    best_route[city1].append(trip['city2'][j])
                    best_route[city2].append(trip['city1'][j])
