        // Validate the bearer token
        if (bearerToken == null || !bearerToken.StartsWith("Bearer "))
        {
            return Task.FromResult(new AuthenticateResult(false, "Invalid bearer token"));
        }

        // Decode the bearer token
        var token = JwtHelper.DecodeJwt(bearerToken);

        // Validate the token
        if (token == null || !token.IsValid)
        {
            return Task.FromResult(new AuthenticateResult(false, "Invalid bearer token"));
        }

        // Get the user identity from the token
        var userIdentity = token.Claims.FirstOrDefault(c => c.Type == "http://schemas.microsoft.com/identity/claims/identity");

        // Return an AuthenticatedResult with the user identity
        return Task.FromResult(new AuthenticateResult(true, userIdentity));
    }
}
```

