```java
public class SecureClass {
    private static final String KEY = "my_secret_key";

    // Encrypt method to encrypt strings
    public String encrypt(String text) {
        try {
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            SecretKeySpec key = new SecretKeySpec(KEY.getBytes(), "AES");
            cipher.init(Cipher.ENCRYPT_MODE, key);
            return Base64.getEncoder().encodeToString(cipher.doFinal(text.getBytes()));
        } catch (Exception e) {
            System.out.println("Error while encrypting: " + e.toString());
        }
        return null;
    }

    // Decrypt method to decrypt encrypted strings
    public String decrypt(String cipherText) {
        try {
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            SecretKeySpec key = new SecretKeySpec(KEY.getBytes(), "AES");
            cipher.init(Cipher.DECRYPT_MODE, key);
            return new String(cipher.doFinal(Base64.getDecoder().decode(cipherText)));
        } catch (Exception e) {
            System.out.println("Error while decrypting: " + e.toString());
        }
        return null;
    }

    // Secure method with access control
    private void secureMethod() {
        // Method logic here
    }

    public static void main(String[] args) {
        SecureClass sc = new SecureClass();
        String text = "Hello World!";
        String cipherText = sc.encrypt(text);
        String decryptedText = sc.decrypt(cipherText);
        System.out.println(decryptedText);

        // sc.secureMethod(); // Compile-time error, method is private
    } 
}
